import unittest

from solucao import soma


class TestMaisDeUmaJanela(unittest.TestCase):
    def test_soma_dois_e_tres(self):
        """a caixa devolve 5 quando recebe 2 e 3"""
        self.assertEqual(soma(2, 3), 5)

    def test_soma_com_zero(self):
        """a caixa devolve o mesmo numero quando recebe zero"""
        self.assertEqual(soma(0, 7), 7)

    def test_soma_de_negativos(self):
        """a caixa devolve 1 quando recebe -2 e 3"""
        self.assertEqual(soma(-2, 3), 1)
